import React from 'react';

function page(title, lead, concept, code, example, comparison) {
  return {
    title,
    content: (
      <>
        <p className="lesson-lead">{lead}</p>
        <section className="lesson-topic">
          <h3>Core idea</h3>
          <p>{concept}</p>
          <pre><code>{code}</code></pre>
        </section>
        <section className="lesson-topic">
          <h3>Try it in context</h3>
          <p>{example}</p>
        </section>
        <p className="lesson-takeaway">{comparison}</p>
      </>
    ),
  };
}

function lecture(title, pages) {
  return { title, pages };
}

function guidedLecture(title, lead, concept, code, example, takeaway) {
  return lecture(title, [
    page(title, lead, concept, code, example, takeaway),
  ]);
}

